mapper.select:
SELECT sdc.id, sdc.name, sdc.code, sdc.description, sdc.status, sdc.extend_schema, sdc.sort_order, sdc.created_at, creator.nickname as created_by_name, sdc.updated_at, updater.nickname as updated_by_name FROM sys_dict_category sdc LEFT JOIN users creator ON sdc.created_by = creator.id LEFT JOIN users updater ON sdc.updated_by = updater.id WHERE sdc.delflag = 0
AND sdc.tenant_id = #{query.tenantId}
AND (sdc.name LIKE CONCAT('%', #{query.keyword}, '%') OR sdc.code LIKE CONCAT('%', #{query.keyword}, '%'))
AND sdc.status = #{query.status}
ORDER BY sdc.sort_order ASC, sdc.created_at DESC
LIMIT #{query.size} OFFSET #{query.offset}

SELECT COUNT(1) FROM sys_dict_category sdc WHERE sdc.delflag = 0
AND sdc.tenant_id = #{query.tenantId}
AND (sdc.name LIKE CONCAT('%', #{query.keyword}, '%') OR sdc.code LIKE CONCAT('%', #{query.keyword}, '%'))
AND sdc.status = #{query.status}

SELECT * FROM sys_dict_category
WHERE code = #{code} 
AND tenant_id = #{tenantId}
AND delflag = 0

    AND id != #{excludeId}

LIMIT 1

SELECT sdc.id, sdc.name, sdc.code, sdc.description, sdc.status, sdc.extend_schema, sdc.sort_order, sdc.created_at, creator.nickname as created_by_name, sdc.updated_at, updater.nickname as updated_by_name FROM sys_dict_category sdc LEFT JOIN users creator ON sdc.created_by = creator.id LEFT JOIN users updater ON sdc.updated_by = updater.id WHERE sdc.status = 1 AND sdc.delflag = 0
AND sdc.tenant_id = #{tenantId}
ORDER BY sdc.sort_order ASC, sdc.name ASC
